        edges = set()
        for u in range(n):
            available_neighbors = [v for v in range(n) if v != u and v not in G[u]]
            neighbors = random.sample(available_neighbors, degree)
            for v in neighbors:
                edges.add((min(u, v), max(u, v)))

        if len(edges) == n * degree // 2:
            break

    for (u, v) in edges:
        G[u][v] = 1
        G[v][u] = 1

    return G

