def memoize(f):
    cache = {}
    def helper(x):
        if x not in cache:            
            cache[x] = f(x)
        return cache[x]
    return helper

@memoize
def Q_dt(g, k=4):
    if len(g) == 1:
        return 0
    else:
        i = g.index(min(g))
        return 1 + max(Q_dt(g[:i], k), Q_dt(g[i+1:], k))

def RSK_insertion_tableau(seq):
    tableau = []
    for x in seq:
        row = []
        while row and row[-1] > x:
            row.pop()
        row.append(x)
        if len(row) > len(tableau):
            tableau.append([])
        tableau[len(row)-1].append(x)
    return tableau

