def gaussian_elimination(A):
    n = len(A)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        for j in range(i+1, n):
            factor = A[j][i] / A[i][i]
            for k in range(n):
                A[j][k] -= factor * A[i][k]
    return A

def matrix_multiplication(A, B):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def asdim(X, d, max_k=32):
    n = len(X)
    best_R = float('inf')
    for k in range(1, max_k+1):
        colors = [random.randint(0, k-1) for _ in X]
        R = float('inf')
        for color in set(colors):
            pieces = []
            for x in X:
                if colors[x] == color:
                    piece = []
                    for y in X:
                        if d(x, y) <= R:
                            piece.append(y)
                    pieces.append(piece)
            min_R = float('inf')
            for piece in pieces:
                min_R = min(min_R, max(d(x, y) for x, y in itertools.combinations(piece, 2)))
            R = min(R, min_R)
        if R < best_R:
            best_R = R
    return n - math.ceil(math.log(best_R + 1))

def d_f(f, x, y):
    s = 0
    for i in range(len(x)):
        if f(x[:i] + (x[i]^y[i],) + x[i+1:]) != f(y[:i] + (x[i]^y[i],) + y[i+1:]):
            s += 1
    return math.ceil(math.log2(s))

def coarse_product(X_f, d_f, X_g, d_g):
    n = len(X_f)
    m = len(X_g)
    X_fg = [i*m + j for i in range(n) for j in range(m)]
