S5_COMM_TABLE = {
    (i, j): (k if k != i and k != j else -1)
    for i in range(5) for j in range(i+1, 5) for k in range(5)
}

def s5_multiply(a, b):
    return S5_MULT_TABLE[a][b]

def s5_commutator(a, b):
