def xor_tree(n):
    if n == 1:
        return [0, 1]
    left = xor_tree(n // 2)
    right = xor_tree(n // 2)
    return [left[i] ^ right[i] for i in range(n)]

def depth_bounded_distinguisher(tree, x, y, R):
    queue = [(x, 0)]
    visited = set()
    while queue:
        node, d = queue.pop(0)
        if node == y or d > R:
            continue
        visited.add(node)
        for i in range(len(tree)):
            if tree[i] == node and i not in visited:
                queue.append((i, d + 1))
    return len(visited)

def build_cochain_spaces(tree, R):
    n = len(tree)
    C0 = [[0] * (n * n) for _ in range(n)]
    C1 = [[0] * (n * n) for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if depth_bounded_distinguisher(tree, i, j, R) <= R:
                C0[i][j] = 1
                C1[i][j] = 1
    return C0, C1

def smith_normal_form(matrix):
    n = len(matrix)
    for k in range(n):
        pivot_row = k + max(range(k, n), key=lambda r: abs(matrix[r][k]))
        matrix[k], matrix[pivot_row] = matrix[pivot_row], matrix[k]
        for i in range(n):
            if i != k:
                factor = matrix[i][k] / matrix[k][k]
                for j in range(n):
                    matrix[i][j] -= factor * matrix[k][j]
    return matrix

def rank_over_Q(matrix):
    n = len(matrix)
    rank = 0
    for k in range(n):
        if matrix[k][k] != 0:
            rank += 1
            for i in range(n):
                if i != k:
                    factor = matrix[i][k] / matrix[k][k]
                    for j in range(k, n):
                        matrix[i][j] -= factor * matrix[k][j]
    return rank

def build_roe_operator(tree, R):
    n = len(tree)
    T = [[0] * (n * n) for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if depth_bounded_distinguisher(tree, i, j, R) <= R:
                T[i][j] = random.choice([-1, 1])
    return T

def trace_pairing(c, T):
    n = len(c)
    return sum(c[i][j] * T[i][j] for i in range(n) for j in range(n))

