from collections import defaultdict

def hamming_distance(x, y):
    return sum(xi != yi for xi, yi in zip(x, y))

def inner_product(a, b):
    return sum(xi * yi for xi, yi in zip(a, b))

class MetricGadget:
    def __init__(self, X, Y, d):
        self.X = X
        self.Y = Y
        self.d = d

    def distance(self, x, y):
        return self.d(x, y)

def gadget_composition(G1, G2):
    X = [(x1, x2) for x1 in G1.X for x2 in G2.X]
    Y = [(y1, y2) for y1 in G1.Y for y2 in G2.Y]
    d_⊕ = lambda (x1, x2), (y1, y2): max(G1.distance(x1, y1), G2.distance(x2, y2))
    return MetricGadget(X, Y, d_⊕)

def lifted_input_space(G, R):
    X = G.X
    Y = G.Y
    d_⊕ = lambda (x1, x2), (y1, y2): max(G.d(x1, y1), G.d(x2, y2))
    return MetricGadget(X, Y, d_⊕)

def asdim_certify(G, R):
    X = G.X
    Y = G.Y
    d = G.d
    n = len(X)
    m = float('inf')

    def is_covered(C):
        for x in X:
            covered = False
            for c in C:
                if d(x, c) <= R:
                    covered = True
                    break
            if not covered:
                return False
        return True

    def greedy_search():
        nonlocal m
        C = []
        while len(C) < n and is_covered(C):
            best_c = None
            best_r = float('inf')
            for x in X:
                r = min(d(x, c) for c in C)
                if r < best_r:
                    best_r = r
                    best_c = x
            if best_c is not None:
                C.append(best_c)
        m = len(C)

    greedy_search()
    return m

def protocol_tree_enumeration(G, f, max_cost):
    X = G.X
    Y = G.Y
    d = G.d

    def is_valid_protocol(protocol):
        for x in X:
            y = f(x)
            if not all(y == f(g) for g in Y if d(x, g) <= protocol.get((x, g), float('inf'))):
                return False
        return True

    def search(current_cost, current_protocol):
        if current_cost > max_cost:
            return False
        if is_valid_protocol(current_protocol):
            return True
        for x in X:
            for y in Y:
                new_protocol = current_protocol.copy()
                new_protocol[(x, y)] = current_cost
                if search(current_cost + 1, new_protocol):
                    return True
        return False

    return search(0, {})

def run_trial(seed: int) -> dict:
