                if all(f[tuple(new_mask)] == f[tuple(new_mask ^ (1 << j))] for j in range(i + 1)):
                    continue
                max_val = max(max_val, dp(i + 1, new_mask))
            return max_val
        return dp(0, mask)

    def Q_dt(f):
