            clauses.append([f'-{y_v}', f'{x_u}'])
            clauses.append([f'-{x_u}', f'-{x_v}', f'y_u'])
            clauses.append([f'-{x_u}', f'-{x_v}', f'y_v'])
        for i in range(n):
            x_i, y_i = literals[i]
            if c[i] == 1:
