        if len(stack) == n:
            leaves += 1
            return True
        var = next((i for i in range(1, n + 1) if assignment[i] is None), None)
        if var is None:
            return False
        assignment[var] = True
        stack.append(var)
        if all(any(clause[i - 1] != assignment[abs(clause[i - 1])] for i in clause) for clause in F):
