        M = [[0] * (2**n) for _ in range(2**n)]
        for i in range(2**n):
            for j in range(2**n):
                a = bin(i)[2:].zfill(n)
                b = bin(j)[2:].zfill(n)
                M[i][j] = f[int(a + b, 2)]
        return M

    def gaussian_elimination(M):
        m, n = len(M), len(M[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(M[j][i]) > abs(M[max_row][i]):
                    max_row = j
            M[i], M[max_row] = M[max_row], M[i]
            if M[i][i] == 0:
