    for i in range(n):
        for j in range(i + 1, n):
            d = hamming_distance(i, j)
            if d <= R:
                F[i].add(j)
                F[j].add(i)
    def dfs(node, visited):
        stack = [node]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
